from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = 10**9

        best_index = [INF] * (max_group + 1)
        for j, e in enumerate(elements):
            if e <= max_group and best_index[e] == INF:
                best_index[e] = j

        best_for_group = [INF] * (max_group + 1)
        for e in range(1, max_group + 1):
            idx = best_index[e]
            if idx == INF:
                continue
            for multiple in range(e, max_group + 1, e):
                if idx < best_for_group[multiple]:
                    best_for_group[multiple] = idx

        return [-1 if best_for_group[g] == INF else best_for_group[g] for g in groups]
